with gaps as (select *, case when lag(started_at) over (partition by device order by started_at, id) is null or started_at > lag(started_at) over (partition by device order by started_at, id) + interval '30' day then 1 else 0 end as is_new_session from sessions), sessions_sessions as (select *, sum(is_new_session) over (partition by device order by started_at, id rows between unbounded preceding and current row) as session_id from gaps) select device, case when session_id >= 9 then 'PREMIUM' else 'STANDARD' end as session_id_tier, round(avg(is_new_session), 2) as avg_is_new_session, count(case when country = 'JP' then 1 end) as jp_count from sessions_sessions group by 1, 2
